css:
.flex {
  display: flex;
  align-items: center;
  justify-content: center;
}
.flex-row {
  flex-direction: row;
}
.button {
  cursor: pointer;
  padding: 12px 20px;
  border-radius: 18px;
  font-size: 1.4rem;
  font-weight: bolder;
  border: solid 1px #767676;
  background: radial-gradient(circle 120px at -10% -80%, #51678c, #161c26);
  color: #fff;
}
.text-let {
  margin-right: 10px;
}
.text-magic {
  margin-left: -10px;
  background: -webkit-linear-gradient(180deg, #ffffff, #ad998b);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-weight: bolder;
}
.svg {
  margin-left: -50px;
}
.portal-line {
  width: 4px;
  height: 30px;
  border-radius: 999px;
  background-color: #fff;
}
.line1 {
  width: 48px;
  height: 12px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    #ffffffa6 0%,
    #eea45aa1 50%,
    #161c2600 100%
  );
  filter: blur(5px);
  transform: rotate(-23deg);
  margin-bottom: -2px;
}
.line2 {
  width: 45px;
  height: 15px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    #ffffffa6 0%,
    #eea45aa1 50%,
    #161c2600 100%
  );
  filter: blur(5px);
}
.line3 {
  width: 48px;
  height: 12px;
  border-radius: 999px;
  background: linear-gradient(
    90deg,
    #ffffffa6 0%,
    #eea45aa1 50%,
    #161c2600 100%
  );
  filter: blur(5px);
  transform: rotate(23deg);
  margin-top: -2px;
}
